let inspected=null;
const STATUS_TEXT={webbed:'Webbed: attacks deal 25% less damage for two turns.',soaked:'Soaked: electric attacks deal 30% extra damage.',ink:'Ink: miss chance rises to 22%. Guard & focus clears it.',pressure:'Pressure: lose 1 focus after acting. Guard & focus clears it.',burn:'Burn: takes 5% maximum HP damage after acting.',poison:'Poison: takes damage after acting.',chill:'Chill: attacks deal 35% less damage.'};
function renderStatuses(){const view=presentation||state,all=[...view.party,...(view.summons||[]),...view.enemies],u=all.find(p=>p.id===inspected)||E.active(view)||view.party[0],box=$('status-area'),preserved=box.querySelector('.status-detail[data-pinned]');box.replaceChildren();if(box.hidden)return;const heading=element('strong',{},u.name),close=element('button',{'aria-label':'Close fighter details',class:'inspect-close',onclick:()=>{box.hidden=true;}},'×');box.append(heading,close);const chips=element('div',{class:'status-chips'});const entries=[];for(const [key,n]of Object.entries(u.status||{}))if(n>0)entries.push([key+' · '+n,STATUS_TEXT[key]||key]);if(E.G.MUTATIONS[u.variant]){const m=E.G.MUTATIONS[u.variant];entries.push([m.name,m.description]);}if(u.guard)entries.push(['Guard','Guard: incoming damage is halved until the next turn.']);if(u.images)entries.push(['Illusions · '+u.images,'False images absorb attacks. Guard & focus exposes them.']);if(u.taunt)entries.push(['Taunt','All enemies target this knight while it lives. High armor reduces incoming damage.']);if(u.side==='party'&&!u.summon)entries.push([P.RACES[u.race||'human'].name,P.RACES[u.race||'human'].passive]);for(const [key,n]of Object.entries(u.cooldowns||{}))if(n>0)entries.push([E.SKILLS[key]?.name+' · '+n,'Recovering for '+n+' own turns.']);if(view.oceanWard&&view.round<=2&&u.side==='party')entries.push(['Dive ward','Reinforced diving equipment: +2 armor for the first two rounds.']);if(view.arena)entries.push([view.arena.kind+' · '+view.arena.rounds,view.arena.kind==='inferno'?'Inferno: lose 2.5% HP after acting.':view.arena.kind==='undertow'?'Undertow: lose 1 focus after acting.':'Gravity: your attacks deal 20% less damage.']);if(u.side==='enemy'){entries.push([E.Elements.label(E.enemyAffinity(u).element),E.Elements.summary(E.enemyAffinity(u))]);const kit=E.C.ENEMY_MOVES[u.enemyType]||[];entries.push([kit.length+' attacks',kit.map(k=>E.SKILLS[k].name+' ['+E.Elements.TYPES[E.SKILLS[k].element].name+'] — '+E.SKILLS[k].description).join('\n')]);}if(!entries.length)entries.push(['Clear','No active status effects.']);for(const [label,desc]of entries){const b=element('button',{class:'status-chip',title:desc},label);const show=()=>{box.querySelector('.status-detail')?.remove();const tip=element('div',{class:'status-detail',role:'tooltip'},desc);tip.style.whiteSpace='pre-line';tip.dataset.unit=u.id;tip.dataset.label=label;if(pinned)tip.dataset.pinned='true';box.append(tip);};b.onmouseenter=b.onfocus=show;let pinned=!!(preserved&&preserved.dataset.unit===u.id&&preserved.dataset.label===label);b.onmouseleave=b.onblur=()=>{if(!pinned)box.querySelector('.status-detail')?.remove();};b.onclick=()=>{pinned=!pinned;if(pinned)show();else box.querySelector('.status-detail')?.remove();};chips.append(b);}box.append(chips);if(preserved&&preserved.dataset.unit===u.id)box.append(preserved);}
function cardsScreen(){showModal('<div class="eyebrow">ABILITIES · BUILD YOUR OWN PATH</div><h2>Your hand.<br>Your rules.</h2><p>Equip up to three cards. They appear under Fight alongside your class attacks. Changes apply at camp or on your next journey.</p><div class="shop-heading"><span class="gold">◈ '+profile.coins+' gold</span><span>'+profile.equippedCards.length+'/3 equipped</span></div><div class="card-grid">'+Object.entries(P.CARDS).map(([id,c],i)=>{const owned=profile.cards.includes(id),equipped=profile.equippedCards.includes(id);return '<article class="ability-card '+(equipped?'equipped':'')+'"><small>'+c.rarity.toUpperCase()+' · '+c.cost+' FOCUS</small><div class="card-art">'+['♜','◇','➶','❄','☽','✦'][i%6]+'</div><strong>'+escape(c.name)+'</strong><p>'+escape(c.description)+'</p><button data-card="'+id+'" '+(!owned&&profile.coins<c.price?'disabled':'')+'>'+(equipped?'Unequip':owned?'Equip card':c.price+' gold · Buy')+'</button></article>';}).join('')+'</div>');document.querySelectorAll('[data-card]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const id=b.dataset.card;await tavern.shop(profile.cards.includes(id)?'equip':'buy','cards',id);await applyProfile();cardsScreen();}catch(e){notify(e.message);b.disabled=false;}});}
function warpScreen(){const p=state?.party.find(p=>p.id===(room?.heroId||'hero'));if(!E.hasAdmin(p))return;showModal('<div class="eyebrow">BRYAN · WARP JUMP</div><h2>Choose a destination.</h2><p>Jump directly to any encounter. No rewards or healing are granted.</p><div class="warp-fields"><select id="warp-campaign" aria-label="Run segment"><option value="1">Encounters 1–30</option><option value="2">Encounters 31–60 · Ocean</option><option value="3">Encounters 61–90 · Sky</option></select><select id="warp-encounter" aria-label="Encounter"></select></div><button class="primary" id="warp-go">Warp jump ↗</button>');const fill=()=>{$('warp-encounter').replaceChildren(...E.routeFor(state,Number($('warp-campaign').value)).map((c,i)=>element('option',{value:i},(i+(Number($('warp-campaign').value)-1)*30+1)+' · '+c.regionName+' · '+c.name)));};$('warp-campaign').value=String(state.act||1);$('warp-campaign').onchange=fill;fill();$('warp-encounter').value=state.stage;$('warp-go').onclick=async()=>{const act=Number($('warp-campaign').value),stage=Number($('warp-encounter').value);if(room){hideModal();sendRoom({type:'warp',act,stage});return;}const before=structuredClone(state);if(!E.warp(state,'hero',act,stage))return;clearTimeout(enemyTimer);target=null;hideModal();save();await transition('world',before);};}
