function accessoriesScreen(){showModal('<div class="eyebrow">COSMETICS · HEAD / BACK / NECK</div><h2>Finishing touches.</h2><p>Wear one accessory in each slot. Accessories are cosmetic and visible in the tavern, battles and cutscenes.</p><div id="accessory-model"></div><div class="shop-heading">◈ '+profile.coins+' gold · '+profile.appearance.accessories.length+'/3 worn</div><div class="merchant-stock">'+Object.entries(P.ACCESSORIES).map(([id,item])=>{const owned=profile.accessories.includes(id),worn=profile.appearance.accessories.includes(id);return '<article class="stock-card"><div><strong>'+escape(item.name)+'</strong><p>'+item.slot.toUpperCase()+' · '+escape(item.description)+'</p></div><button data-accessory="'+id+'" '+(!owned&&profile.coins<item.price?'disabled':'')+'>'+(worn?'Take off':owned?'Wear':item.price+' gold · Buy')+'</button></article>';}).join('')+'</div><button id="accessory-back" class="text-button">Back to customization</button>');const hero=E.hero('preview',profile.name,profile.job);E.applyLoadout(hero,profile);modelPreview.show($('accessory-model'),hero,'forest',false);document.querySelectorAll('[data-accessory]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const id=b.dataset.accessory;await tavern.shop(profile.accessories.includes(id)?'equip':'buy','accessories',id);await applyProfile();accessoriesScreen();}catch(error){notify(error.message);b.disabled=false;}});$('accessory-back').onclick=customizeScreen;}
let shopTab='classes';
function shopScreen(){showModal('<div class="eyebrow">ALDEN · QUARTERMASTER</div><h2>Something for<br>the road?</h2><p>“A warmer coat, a sharper edge, a new path. Take your time.”</p><div class="shop-heading"><span class="gold">◈ '+profile.coins+' gold</span><span>1 coin per fight · 5 per campaign boss · 150 welcome gold</span></div><nav class="shop-tabs">'+['classes','weapons','races','accessories'].map(type=>'<button data-shop-tab="'+type+'" class="'+(type===shopTab?'active':'')+'">'+type+'</button>').join('')+'</nav><div class="merchant-stock">'+Object.entries(shopTab==='classes'?E.CLASSES:shopTab==='weapons'?P.WEAPONS:shopTab==='accessories'?P.ACCESSORIES:P.RACES).map(([id,item])=>{const owned=profile[shopTab].includes(id),equipped=shopTab==='accessories'?profile.appearance.accessories.includes(id):profile[shopTab==='classes'?'job':shopTab==='races'?'race':'weapon']===id,desc=shopTab==='accessories'?item.slot+' · '+item.description:shopTab==='classes'?E.SKILLS[item.skill].description+' Ultimate: '+E.SKILLS[item.ultimate].name+' — '+E.SKILLS[item.ultimate].description:shopTab==='races'?item.passive+' Ultimate: '+E.SKILLS[item.ultimate].name+' — '+E.SKILLS[item.ultimate].description:'+'+item.atk+' attack · '+E.SKILLS[item.skill].name+' — '+E.SKILLS[item.skill].description;return '<article class="stock-card"><div><strong>'+escape(item.name)+'</strong><p>'+escape(desc)+'</p></div><button data-stock="'+id+'" data-action="'+(owned?'equip':'buy')+'" '+(equipped||!owned&&profile.coins<item.price?'disabled':'')+'>'+(equipped?'Equipped':owned?'Equip':item.price+' gold')+'</button></article>';}).join('')+'</div><button class="text-button" id="merchant-back">Back to the fire →</button>');
 document.querySelectorAll('[data-shop-tab]').forEach(button=>button.onclick=()=>{shopTab=button.dataset.shopTab;shopScreen();});document.querySelectorAll('[data-stock]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await tavern.shop(button.dataset.action,shopTab,button.dataset.stock);if(button.dataset.action==='equip')await applyProfile();tone('menu');shopScreen();}catch(error){notify(error.message);button.disabled=false;}});$('merchant-back').onclick=()=>{hideModal();};
}
